{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "root",
      "type": "ReactElement<NavigationScreenProps>",
      "description": "The root screen, a NavigationScreen. It has no Back button.",
      "required": true
    },
    {
      "name": "path",
      "type": "ReadonlyArray<T>",
      "description": "The entries pushed on the root, bottom first. Adding one at the end pushes its screen; removing the last pops it; removing several pops straight back to the new top.",
      "required": true
    },
    {
      "name": "onPathChange",
      "type": "(path: T[]) => void",
      "description": "Called with the new path when a screen pushes or pops (useNavigationStack), Back is pressed, or a back swipe is released past the point of no return.",
      "required": true
    },
    {
      "name": "renderScreen",
      "type": "(entry: T, index: number) => ReactElement<NavigationScreenProps>",
      "description": "Renders the screen for an entry: a NavigationScreen.",
      "required": true
    },
    {
      "name": "getKey",
      "type": "(entry: T, index: number) => string | number",
      "description": "A stable key per entry, so a screen keeps its state while others are pushed on it. Defaults to the entry's position."
    },
    {
      "name": "isInteractivePopEnabled",
      "type": "boolean",
      "description": "Whether the back swipe pops: a sideways drag anywhere in the content, under any pointer (a finger, a pen or a mouse drag), and in a web app opened from the home screen also a finger's swipe from the leading screen edge. In a browser tab that edge stays the browser's own back swipe, and on Android the system back owns both screen edges.",
      "default": "true"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible name of the navigator region."
    },
    {
      "name": "title",
      "type": "string",
      "description": "Shown in the bar while the screen is on top, and read first when it arrives.",
      "required": true
    },
    {
      "name": "backTitle",
      "type": "string",
      "description": "What Back reads on the screen pushed on top of this one. Defaults to title."
    },
    {
      "name": "titleDisplayMode",
      "type": "'large' | 'inline'",
      "description": "How the title shows. 'large' puts it above the content in a large bold type, scrolling with the content; once it has scrolled under the bar, the bar shows the title instead. Use it for a top-level screen, as iOS does.",
      "default": "'inline'"
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Content at the end of the bar while the screen is on top."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "The screen's content. It scrolls on its own and keeps its scroll position while covered."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
